&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-Dhistoire.html&quot; title=&quot;Dons d&amp;#39;histoire&quot;&gt;Dons d&#39;histoire (GC)&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-&#201;sot&#233;riques.html&quot; title=&quot;Dons &#233;sot&#233;riques&quot;&gt;Dons &#233;sot&#233;riques (PU)&lt;/a&gt;&lt;/li&gt;
